    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
70→      recipientId: tenant.userIds.member,
      kind: "comment_created",
      title,
      body: title,
      href: "/issues/1",
      actorId: null,
      channels: ["email"],
