type WallClock = {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
  millisecond: number;
};

/** Rejects a zone name `Intl` does not recognise. */
export function assertKnownTimeZone(timeZone: string): void {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
  } catch {
    throw new RangeError(`Unknown time zone: ${timeZone}`);
  }
}

function zonedParts(date: Date, timeZone: string): WallClock {
  assertKnownTimeZone(timeZone);
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  const map: Record<string, string> = {};
  for (const part of formatted.formatToParts(date)) {
    if (part.type !== "literal") map[part.type] = part.value;
  }
  let hour = Number(map.hour);
  if (hour === 24) hour = 0;
  return {
    year: Number(map.year),
    month: Number(map.month),
    day: Number(map.day),
    hour,
    minute: Number(map.minute),
    second: Number(map.second),
    millisecond: date.getUTCMilliseconds(),
  };
}

function pad(value: number, width: number): string {
  return String(value).padStart(width, "0");
}

function formatYmd(year: number, month: number, day: number): string {
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

function shiftCalendarDate(
  parts: Pick<WallClock, "year" | "month" | "day">,
  days: number,
): Pick<WallClock, "year" | "month" | "day"> {
  const shifted = new Date(Date.UTC(parts.year, parts.month - 1, parts.day + days));
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
  };
}

/**
 * Every UTC instant that displays as the requested wall-clock time. Empty when
 * the clock skips that time (a DST spring-forward). Two entries when the clock
 * repeats it (a fall-back).
 */
function matchingInstants(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  millisecond: number,
  timeZone: string,
): Date[] {
  const desired = Date.UTC(year, month - 1, day, hour, minute, second, millisecond);
  const hits = new Set<number>();
  for (let offsetMin = -16 * 60; offsetMin <= 16 * 60; offsetMin += 15) {
    const utc = desired - offsetMin * 60_000;
    const parts = zonedParts(new Date(utc), timeZone);
    if (
      parts.year === year &&
      parts.month === month &&
      parts.day === day &&
      parts.hour === hour &&
      parts.minute === minute &&
      parts.second === second &&
      parts.millisecond === millisecond
    ) {
      hits.add(utc);
    }
  }
  return [...hits].sort((a, b) => a - b).map((utc) => new Date(utc));
}

/** Wall-clock time that does not exist resolves to the following valid instant. */
function resolveWall(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  millisecond: number,
  timeZone: string,
): Date {
  const found = matchingInstants(
    year,
    month,
    day,
    hour,
    minute,
    second,
    millisecond,
    timeZone,
  );
  if (found.length > 0) return found[0] ?? new Date(NaN);

  let utc = Date.UTC(year, month - 1, day, hour, minute, second, millisecond);
  const want = utc;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const parts = zonedParts(new Date(utc), timeZone);
    const got = Date.UTC(
      parts.year,
      parts.month - 1,
      parts.day,
      parts.hour,
      parts.minute,
      parts.second,
      parts.millisecond,
    );
    if (got === want) return new Date(utc);
    utc += want - got;
  }
  return new Date(utc);
}

/** `YYYY-MM-DD` of `value` on the workspace clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = zonedParts(parseIso(value), timeZone);
  return formatYmd(parts.year, parts.month, parts.day);
}

/** Hour 0–23 of `value` on the workspace clock. */
export function localHour(value: Date, timeZone: string): number {
  return zonedParts(value, timeZone).hour;
}

/**
 * UTC instant at which the workspace's calendar day containing `reference`
 * began (local midnight).
 */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const parts = zonedParts(reference, timeZone);
  return toIsoTimestamp(
    resolveWall(parts.year, parts.month, parts.day, 0, 0, 0, 0, timeZone),
  );
}

/** Local midnight of a `YYYY-MM-DD` calendar date on the workspace clock. */
export function startOfLocalDate(day: string, timeZone: string): IsoTimestamp {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(day);
  if (!match) throw new RangeError(`Malformed calendar day: "${day}"`);
  return toIsoTimestamp(
    resolveWall(
      Number(match[1]),
      Number(match[2]),
      Number(match[3]),
      0,
      0,
      0,
      0,
      timeZone,
    ),
  );
}

/**
 * True once the workspace calendar day that contains `dueAt` has ended.
 * The due day itself is not overdue, whatever time of day `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The digest window ending at the most recent local `digestHour:00` at or
 * before `reference`. It starts at that same local hour on the previous
 * calendar day, so a DST change makes the window 23 or 25 hours long. When
 * today's hour has not arrived yet, the window is the one that ended yesterday.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHour}`);
  }

  const today = zonedParts(reference, timeZone);
  const todayHits = matchingInstants(
    today.year,
    today.month,
    today.day,
    digestHour,
    0,
    0,
    0,
    timeZone,
  ).filter((instant) => instant.getTime() <= reference.getTime());

  let end: Date;
  if (todayHits.length > 0) {
    end = todayHits[todayHits.length - 1] ?? reference;
  } else {
    const yesterday = shiftCalendarDate(today, -1);
    const yesterdayHits = matchingInstants(
      yesterday.year,
      yesterday.month,
      yesterday.day,
      digestHour,
      0,
      0,
      0,
      timeZone,
    ).filter((instant) => instant.getTime() <= reference.getTime());
    end =
      yesterdayHits[yesterdayHits.length - 1] ??
      resolveWall(
        yesterday.year,
        yesterday.month,
        yesterday.day,
        digestHour,
        0,
        0,
        0,
        timeZone,
      );
  }

  const endParts = zonedParts(end, timeZone);
  const startDay = shiftCalendarDate(endParts, -1);
  const startHits = matchingInstants(
    startDay.year,
    startDay.month,
    startDay.day,
    digestHour,
    0,
    0,
    0,
    timeZone,
  );
  const start =
    startHits[0] ??
    resolveWall(
      startDay.year,
      startDay.month,
      startDay.day,
      digestHour,
      0,
      0,
      0,
      timeZone,
    );

  return { start: toIsoTimestamp(start), end: toIsoTimestamp(end) };
