import {
  addDays,
  digestWindow,
  formatDate,
  formatRelative,
  isOverdue,
  now,
  parseIso,
} from "@/lib/date";

it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(true);
  expect(isOverdue(iso("2026-03-15T12:00:01.000Z"), REFERENCE)).toBe(false);
});

input.new_string:
it("treats a due date as overdue only after its calendar day has ended", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
  // Same UTC day as the reference, earlier or later: not overdue yet.
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T23:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
  // 2026-03-14T16:00Z is still 15 Mar in Tokyo, so it is not overdue at noon UTC.
  expect(
    isOverdue(iso("2026-03-14T16:00:00.000Z"), REFERENCE, "Asia/Tokyo"),
  ).toBe(false);
  // The next Tokyo midnight (15:00Z on the 15th) ends that day.
  expect(
    isOverdue(
      iso("2026-03-14T16:00:00.000Z"),
      new Date("2026-03-15T15:00:00.000Z"),
      "Asia/Tokyo",
    ),
  ).toBe(true);
});

it("names the calendar date and the local midnight in a zone", () => {
  expect(localDate(iso("2026-03-15T15:30:00.000Z"), "Asia/Tokyo")).toBe("2026-03-16");
  expect(localDate(iso("2026-03-15T15:30:00.000Z"), "UTC")).toBe("2026-03-15");
  expect(startOfLocalDay(new Date("2026-03-15T16:00:00.000Z"), "Asia/Tokyo")).toBe(
    "2026-03-15T15:00:00.000Z",
  );
  expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
});

