  it("rejects a digest hour outside 0-23", () => {
    expect(() => digestWindow(24, REFERENCE)).toThrow(RangeError);
    expect(() => digestWindow(-1, REFERENCE)).toThrow(RangeError);
  });

  it("spans 23 or 25 hours across a DST change", () => {
    // US spring forward: 2026-03-08 02:00. Window ending that morning at 08:00.
    const spring = digestWindow(
      8,
      new Date("2026-03-08T12:00:00.000Z"),
      "America/New_York",
    );
    expect(spring.end).toBe("2026-03-08T12:00:00.000Z");
    expect(spring.start).toBe("2026-03-07T13:00:00.000Z");

    // US fall back: 2026-11-01 02:00. Window ending that morning at 08:00.
    const fall = digestWindow(
      8,
      new Date("2026-11-01T13:30:00.000Z"),
      "America/New_York",
    );
    expect(fall.end).toBe("2026-11-01T13:00:00.000Z");
    expect(fall.start).toBe("2026-10-31T12:00:00.000Z");
  });

  it("keeps notifications after the local hour out of an in-progress digest window", () => {
    const window = digestWindow(9, new Date("2026-06-01T09:30:00.000Z"), "UTC");
    expect(window.end).toBe("2026-06-01T09:00:00.000Z");
    expect(window.start).toBe("2026-05-31T09:00:00.000Z");
  });
});

