it("runs the digest during the workspace-local digest hour", () => {
  const org = {
    ...tenant.org,
    settings: { ...tenant.org.settings, digestHourUtc: 7, timeZone: "UTC" },
  };

  expect(shouldRunForOrg(org, NOW)).toBe(true);
  expect(
    shouldRunForOrg(org, new Date("2026-06-01T07:30:00.000Z")),
  ).toBe(true);
  expect(
    shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
  ).toBe(false);
  expect(
    shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
  ).toBe(false);

  const tokyo = {
    ...org,
    settings: { ...org.settings, digestHourUtc: 9, timeZone: "Asia/Tokyo" },
  };
  // 00:30Z is 09:30 in Tokyo; 23:30Z the previous day is 08:30.
  expect(shouldRunForOrg(tokyo, new Date("2026-06-01T00:30:00.000Z"))).toBe(true);
  expect(shouldRunForOrg(tokyo, new Date("2026-05-31T23:30:00.000Z"))).toBe(false);
});

