/** Wall-clock time that does not exist resolves to the following valid instant. */
function resolveWall(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  millisecond: number,
  timeZone: string,
): Date {
  const found = matchingInstants(
    year,
    month,
    day,
    hour,
    minute,
    second,
    millisecond,
    timeZone,
  );
  if (found.length > 0) return found[0] ?? new Date(NaN);

  let utc = Date.UTC(year, month - 1, day, hour, minute, second, millisecond);
  const want = utc;
  for (let attempt = 0; attempt < 4; attempt += 1) {
    const parts = zonedParts(new Date(utc), timeZone);
    const got = Date.UTC(
      parts.year,
      parts.month - 1,
      parts.day,
      parts.hour,
      parts.minute,
      parts.second,
      parts.millisecond,
    );
    if (got === want) return new Date(utc);
    utc += want - got;
  }
  return new Date(utc);
}

