/**
 * Wall-clock time that does not exist (a DST spring-forward) resolves to the
 * next valid instant on that calendar day — the time the clock jumps to.
 */
function resolveWall(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
  millisecond: number,
  timeZone: string,
): Date {
  const found = matchingInstants(
    year,
    month,
    day,
    hour,
    minute,
    second,
    millisecond,
    timeZone,
  );
  if (found.length > 0) return found[0] ?? new Date(NaN);

  const midnight = matchingInstants(year, month, day, 0, 0, 0, 0, timeZone)[0];
